package com.company.orderapproval.customer.location.repository;
import com.company.orderapproval.customer.location.entity.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface BusinessCustomerLocationRepository extends JpaRepository<BusinessCustomerLocation,UUID>{ Optional<BusinessCustomerLocation> findByBusinessCustomerIdAndLocationCode(UUID customerId,String code); Page<BusinessCustomerLocation> findByBusinessCustomerId(UUID customerId,Pageable p); @Query("select l from BusinessCustomerLocation l where l.businessCustomerId=:customerId and (:search is null or :search='' or lower(l.locationName) like lower(concat('%',:search,'%')) or lower(l.city) like lower(concat('%',:search,'%'))) and (:status is null or l.status=:status)") Page<BusinessCustomerLocation> search(@Param("customerId") UUID customerId,@Param("search") String search,@Param("status") BusinessCustomerLocationStatus status,Pageable p); }
